local TIPBOX
local function mkTip()
    local parent
    local okh, h = pcall(function() return gethui() end)
    if okh and h then parent = h end
    if not parent then
        local okc, c = pcall(function() return game:GetService("CoreGui") end)
        if okc and c then parent = c end
    end
    if not parent then
        local okp, p = pcall(function() return game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui", 5) end)
        if okp and p then parent = p end
    end
    if not parent then return nil end
    local okb, box = pcall(function()
        local g = Instance.new("ScreenGui")
        g.Name = "FengcunBoot"
        g.IgnoreGuiInset = true
        g.ResetOnSpawn = false
        g.DisplayOrder = 999
        g.Parent = parent
        local b = Instance.new("TextLabel")
        b.AnchorPoint = Vector2.new(0.5, 0)
        b.Position = UDim2.new(0.5, 0, 0, 96)
        b.Size = UDim2.fromOffset(470, 42)
        b.BackgroundColor3 = Color3.fromRGB(12, 14, 20)
        b.BackgroundTransparency = 0.08
        b.TextColor3 = Color3.fromRGB(255, 255, 255)
        b.Font = Enum.Font.GothamBold
        b.TextSize = 16
        b.Text = ""
        b.Parent = g
        local cr = Instance.new("UICorner")
        cr.CornerRadius = UDim.new(0, 9)
        cr.Parent = b
        local st = Instance.new("UIStroke")
        st.Color = Color3.fromRGB(90, 140, 255)
        st.Transparency = 0.45
        st.Parent = b
        return b
    end)
    if okb then return box end
    return nil
end

TIPBOX = mkTip()
if not TIPBOX then
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {Title = "封存木材", Text = "提示框不可用，但仍在加载", Duration = 5})
    end)
end

local TOKEN = 0
local function tip(text, hold)
    print("[封存木材] " .. tostring(text))
    if not TIPBOX then return end
    TOKEN = TOKEN + 1
    local my = TOKEN
    pcall(function()
        TIPBOX.Text = text
        TIPBOX.Visible = true
    end)
    if hold and hold > 0 then
        task.delay(hold, function()
            if TOKEN == my then
                pcall(function() TIPBOX.Visible = false end)
            end
        end)
    end
end

