if #P ~= EXPECT then
    tip("密文不完整 · 期望 " .. EXPECT .. " 实际 " .. #P, 30)
    error("[fengcun] 密文长度异常")
end

local HEXV = {}
for i = 48, 57 do HEXV[i] = i - 48 end
for i = 65, 70 do HEXV[i] = i - 55 end
for i = 97, 102 do HEXV[i] = i - 87 end

local t0 = os.clock()
local pos = 0
local S = P:gsub("(.)(.)", function(a, b)
    pos = pos + 1
    local v = HEXV[string.byte(a)] * 16 + HEXV[string.byte(b)]
    return string.char(bit32.bxor(v, KEY, bit32.band(pos * 31, 255)))
end)
local cost = math.floor((os.clock() - t0) * 1000)

tip("解码完成 · " .. #S .. " 字节 · " .. cost .. "ms", 0)

local F, E = loadstring(S)
if not F then
    tip("解码失败 · " .. tostring(E), 30)
    error("[fengcun] " .. tostring(E))
end

tip("正在启动面板…", 0)

local ok, err = pcall(F)
if not ok then
    tip("运行出错 · " .. tostring(err), 30)
    error("[fengcun] " .. tostring(err))
end

tip("已启动 · 若没面板请看白名单", 10)
